package io.github.jordanwoodson.patches.rumble.icon

import app.morphe.patcher.patch.PatchException
import app.morphe.patcher.patch.resourcePatch
import io.github.jordanwoodson.patches.rumble.shared.Constants.COMPATIBILITY_RUMBLE
import io.github.jordanwoodson.patches.rumble.shared.RUMBLE
import java.nio.file.Files
import java.nio.file.StandardCopyOption

// Generated by `bin/app-icon rumble <artwork>` into patches/src/main/resources/rumble/icon/.
// Each file replaces the one Rumble ships under the same name, so resource IDs and the
// manifest's @mipmap/ic_launcher references stay untouched.
private val ICON_FILES = listOf(
    "drawable/ic_launcher_background.xml",
    "drawable/ic_launcher_foreground.xml",
    "mipmap-anydpi/ic_launcher.xml",
    "mipmap-anydpi/ic_launcher_round.xml",
) + listOf("mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi").flatMap { dpi ->
    listOf("mipmap-$dpi/ic_launcher.webp", "mipmap-$dpi/ic_launcher_round.webp")
}

@Suppress("unused")
val lurkIconPatch = resourcePatch(
    name = "Lurk icon",
    description = "Replaces Rumble's launcher icon with the Lurk icon, including the themed icon on Android 13+.",
) {
    compatibleWith(COMPATIBILITY_RUMBLE)

    execute {
        val targets = ICON_FILES.associateWith { get("res/$it") }
        val missing = targets.filterValues { !it.isFile }.keys
        if (missing.isNotEmpty()) {
            throw PatchException("Rumble: launcher icon files not found: ${missing.joinToString()}. " +
                "This patch targets Rumble ${RUMBLE.version}; recheck res/ before updating compatibility.")
        }

        val loader = object {}.javaClass.classLoader
        targets.forEach { (path, target) ->
            val icon = loader.getResourceAsStream("rumble/icon/$path")
                ?: throw PatchException("Bundled icon file missing: rumble/icon/$path")
            icon.use { Files.copy(it, target.toPath(), StandardCopyOption.REPLACE_EXISTING) }
        }
    }
}
